{"hechos": [
{"id": "H1", "texto": "Un derrumbe/deslizamiento de tierra bloqueó por completo la vía entre Altamira y Río Claro", "tipo": "dato", "paginas": ["P1", "P2", "P3", "P4", "P5"]},
{"id": "H2", "texto": "El derrumbe ocurrió en el kilómetro 23, en La Curva del Diablo", "tipo": "dato", "paginas": ["P1", "P2", "P3", "P4", "P5"]},
{"id": "H3", "texto": "Alrededor de 400 vehículos quedaron detenidos/atrapados por el bloqueo", "tipo": "dato", "paginas": ["P1", "P2", "P3", "P4", "P5"]},
{"id": "H4", "texto": "La vía se reabriría/habilitaría en unas 48 horas (dos días)", "tipo": "dato", "paginas": ["P1", "P2", "P3", "P4", "P5"]},
{"id": "H5", "texto": "Las autoridades calculan que la vía se habilitará en 48 horas", "tipo": "atribucion", "paginas": ["P1", "P4"]},
{"id": "H6", "texto": "Un operario de maquinaria anónimo dijo que en la zona había grietas desde hace meses", "tipo": "dato", "paginas": ["P2", "P4", "P5"]},
{"id": "H7", "texto": "Los vehículos quedaron atrapados a lado y lado del derrumbe", "tipo": "dato", "paginas": ["P4"]},
{"id": "H8", "texto": "La información se está compartiendo en grupos de WhatsApp", "tipo": "atribucion", "paginas": ["P3", "P4", "P5"]}
]}
